insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'cte_99_v1'
from (values
('127.756.d.16',3,'After a tornado, a CERT volunteer fills out a damage form listing addresses, injuries and resources used. This researches the:','["documentation required during a disaster response", "sports scores", "menu for a picnic", "bus schedule"]'::jsonb,0,'Disaster response is documented for coordination and records.','original'),
('127.756.d.16',4,'Documentation during a disaster response is important because it:','["hides mistakes", "records actions, needs and resources for responders and officials", "replaces all training", "slows rescue work"]'::jsonb,1,'Records support coordination and later review.','original'),
('127.756.d.1.A',3,'A neighborhood CERT member helps hand out flyers before storm season, checks on neighbors during the storm and assists with cleanup afterward. This compares CERT roles:','["only before", "only during", "before, during and after a disaster", "only after"]'::jsonb,2,'CERT roles span all phases.','original'),
('127.756.d.1.A',4,'Before a disaster, a typical CERT role is to:','["give legal rulings", "drive ambulances", "lead the national response", "teach neighbors preparedness and help plan"]'::jsonb,3,'Preparedness education is a CERT function.','original'),
('127.756.d.1.B',3,'A coastal CERT team trains for hurricanes while a plains team trains for tornadoes and wildfire. This analyzes how CERT members respond to:','["hazards common to their area", "only man-made hazards", "every hazard in the world", "no hazards"]'::jsonb,0,'Training is tailored to local hazards.','original'),
('127.756.d.1.B',4,'CERT training is adjusted to a community mainly because:','["hazards never change", "different areas face different likely hazards", "training is optional", "all areas are identical"]'::jsonb,1,'Local risks vary.','original'),
('127.756.d.1.C',3,'A volunteer learns that Texas law gives certain protection to trained disaster volunteers acting in good faith. This analyzes:','["school policies", "traffic fines", "state and local laws that protect first responders", "tax breaks only"]'::jsonb,2,'Laws protect responders acting within training.','original'),
('127.756.d.1.C',4,'A legal protection like a Good Samaritan law is meant to:','["ban volunteers", "prevent all aid", "punish helpers", "encourage people to help in emergencies without fear of unfair lawsuits"]'::jsonb,3,'It protects good-faith helpers.','original'),
('127.756.d.2.A',3,'A flood and a hurricane fall in one group and a chemical spill and a power-plant accident in another. This classifies disasters as:','["natural and man-made", "big and small", "loud and quiet", "fast and slow"]'::jsonb,0,'Disasters are natural or man-made.','original'),
('127.756.d.2.A',4,'Which is a man-made disaster?','["an earthquake", "a chemical plant explosion", "a drought", "a hurricane"]'::jsonb,1,'Industrial accidents are man-made.','original'),
('127.756.d.2.B',3,'A report says a wildfire started from a campfire left burning and spread because of high winds and dry brush. This identifies:','["school subjects", "rules of a game", "common causes of disasters", "shop prices"]'::jsonb,2,'Accidents, weather and human error cause disasters.','original'),
('127.756.d.2.B',4,'A disaster caused by weather conditions like heavy rain is a:','["terror plot", "accidental spill", "software bug", "natural cause of disaster"]'::jsonb,3,'Weather causes natural disasters.','original'),
('127.756.d.3.A',3,'CERT trainees list flying debris, downed power lines and contaminated water after a hurricane. These are:','["potential hazards of a disaster", "party supplies", "benefits of a disaster", "fun activities"]'::jsonb,0,'Disasters create many hazards.','original'),
('127.756.d.3.A',4,'Which hazard is commonly associated with a flood?','["snow", "contaminated water", "rockfall only", "volcanic ash"]'::jsonb,1,'Floodwater can be contaminated.','original'),
('127.756.d.3.B',3,'A team shuts off gas lines, secures loose furniture and moves stored chemicals to high shelves to limit damage. These are:','["ways to ignore risk", "ways to hide danger", "strategies used to manage hazards and reduce impact", "ways to cause hazards"]'::jsonb,2,'Mitigation reduces impact.','original'),
('127.756.d.3.B',4,'Anchoring a tall bookcase to the wall before an earthquake is an example of:','["a hazard", "ignoring risk", "a response delay", "hazard mitigation"]'::jsonb,3,'Securing items prevents injury.','original'),
('127.756.d.3.C',3,'A handout lists steps to take before, during and after a disaster, such as building a kit, sheltering and cleaning up safely. This summarizes:','["measures taken before, during and after a disaster", "only rumors", "only cleaning", "only recovery steps"]'::jsonb,0,'Preparedness spans phases.','original'),
('127.756.d.3.C',4,'Preparing an evacuation plan is a step taken:','["never", "before a disaster", "after the disaster", "only during cleanup"]'::jsonb,1,'Plans are made in advance.','original'),
('127.756.d.4.A',3,'A family draws their home''s floor plan, marks two exits from every room and picks a meeting place outside. This is a:','["travel plan", "party plan", "fire response plan and evacuation route", "cooking plan"]'::jsonb,2,'Escape plans save lives.','original'),
('127.756.d.4.A',4,'A good home fire escape plan includes two ways out of each room and a:','["list of recipes", "TV schedule", "parking lot map", "meeting place outside"]'::jsonb,3,'Everyone should meet at a safe place.','original'),
('127.756.d.4.B',3,'A family prepares for a tornado by choosing a basement corner as the place to take cover. This is a response plan with a:','["safe shelter location", "picnic area", "storage list", "game room"]'::jsonb,0,'Shelter plans identify safe locations.','original'),
('127.756.d.4.B',4,'During a tornado warning at home without a basement, the safest place is usually:','["near a large window", "an interior room on the lowest floor away from windows", "outside", "a car in the driveway"]'::jsonb,1,'Interior rooms offer protection.','original'),
('127.756.d.5.A',3,'A volunteer packs bandages, gloves, gauze, tape, antiseptic wipes and a thermometer in a bag for the car. This identifies:','["tools for painting", "tools for cooking", "components of a first aid kit for home and vehicle", "toys for kids"]'::jsonb,2,'Kits hold basic medical supplies.','original'),
('127.756.d.5.A',4,'Which item belongs in a basic first aid kit?','["a deck of cards", "a hammer only", "a phone cover", "sterile gauze pads"]'::jsonb,3,'Gauze controls bleeding.','original'),
('127.756.d.5.B',3,'A list includes a flashlight, battery-powered radio, extra batteries and a whistle for a disaster kit. These are:','["essential tools and supplies for disaster supply kits", "decorations", "furniture", "toys"]'::jsonb,0,'Basic tools help in emergencies.','original'),
('127.756.d.5.B',4,'A battery-powered or hand-crank radio is a useful kit item because it lets you:','["play games", "get emergency information if power is out", "bake food", "charge TVs"]'::jsonb,1,'News and alerts continue.','original'),
('127.756.d.5.C',3,'A family packs water, canned food, a manual can opener, blankets, clothes and important papers. These are appropriate:','["office supplies", "luxuries", "food, water, clothing and household items for a disaster kit", "party items"]'::jsonb,2,'Kits must meet basic needs.','original'),
('127.756.d.5.C',4,'Emergency planners generally recommend storing about how much water per person per day?','["one cup", "none", "ten gallons", "one gallon"]'::jsonb,3,'One gallon per person per day.','original'),
('127.756.d.5.D',3,'In a drill, volunteers help fire crews with traffic, staging and search while keeping out of dangerous areas. This simulates:','["assisting first responders in fire safety and search and rescue", "acting alone", "freelancing", "avoiding responders"]'::jsonb,0,'CERT supports, not replaces, responders.','original'),
('127.756.d.5.D',4,'When assisting first responders, CERT volunteers should:','["act independently", "work under direction and within their training", "ignore officers", "enter all hazards"]'::jsonb,1,'Teamwork and limits keep people safe.','original'),
('127.756.d.5.E',3,'A volunteer reviews how the Volunteers in Police Service and CERT programs include fire safety in preparedness. This identifies:','["game rules", "hobbies", "fire safety components of disaster preparedness in volunteer programs", "unrelated topics"]'::jsonb,2,'Fire safety is part of preparedness.','original'),
('127.756.d.5.E',4,'Fire safety in a disaster preparedness program includes learning how to:','["start fires", "avoid all training", "fight large fires alone", "use extinguishers and shut off utilities safely"]'::jsonb,3,'Basic skills limit damage.','original'),
('127.756.d.6.A',3,'A CERT member walks through a neighbor''s home checking smoke alarms, cords and cooking areas. This is a:','["fire safety assessment", "remodel", "yard sale", "party"]'::jsonb,0,'CERT teaches home fire safety.','original'),
('127.756.d.6.A',4,'A home fire safety assessment checks for:','["paint colors", "working smoke alarms and overloaded outlets", "TV channels", "furniture styles"]'::jsonb,1,'Alarms and electrical hazards matter.','original'),
('127.756.d.6.B',3,'Two volunteers enter a damaged building together so each can watch over the other. This is a safety precaution known as the:','["speed rule", "solo rule", "buddy system", "loud rule"]'::jsonb,2,'Buddies provide mutual protection.','original'),
('127.756.d.6.B',4,'Why do CERT members use the buddy system?','["to carry less", "to talk more", "to go faster", "So they can watch out for each other and get help if needed"]'::jsonb,3,'Two sets of eyes are safer.','original'),
('127.756.d.6.C',3,'CERT trainees predict where cleaning chemicals, paint, pesticides and fuels are stored in a home and in a business. This identifies:','["locations of hazardous materials in homes and businesses", "locations of parks", "locations of stores", "locations of treasure"]'::jsonb,0,'Knowing where hazmat is helps safety.','original'),
('127.756.d.6.C',4,'Which place in a home is most likely to store hazardous materials?','["a bookshelf", "a garage or utility room", "a pillow", "a window sill"]'::jsonb,1,'Garages hold chemicals and fuels.','original'),
('127.756.d.6.D',3,'A responder uses the limit, isolate, eliminate, separate approach to control a leak. This is the:','["SMART method", "MAPS method", "LIES method", "STOP method"]'::jsonb,2,'LIES: limit, isolate, eliminate, separate.','original'),
('127.756.d.6.D',4,'In the LIES method, the first ''L'' stands for:','["leave", "listen", "lift", "limit"]'::jsonb,3,'Limit exposure to hazards.','original'),
('127.756.d.7.A',3,'A trainer explains that a small flame can spread when it reaches more fuel, air and heat. This explains how fires start and:','["what perpetuates fires", "how to cook", "how to travel", "how to paint"]'::jsonb,0,'Fires continue with fuel, heat and oxygen.','original'),
('127.756.d.7.A',4,'A fire is perpetuated when it has a continuing supply of:','["sand", "fuel, heat and oxygen", "cold air", "water"]'::jsonb,1,'All three keep burning.','original'),
('127.756.d.7.B',3,'CERT trainees name the three elements a fire needs to start and continue. This identifies:','["parts of a kit", "ranks of volunteers", "the elements required for a fire", "types of tools"]'::jsonb,2,'Remove one element to stop the fire.','original'),
('127.756.d.7.B',4,'Removing which element would stop a fire from burning?','["color", "noise", "light", "oxygen, fuel or heat"]'::jsonb,3,'Remove one leg of the triangle.','original'),
('127.756.d.7.C',3,'A volunteer lists the hazards of paper piles, gasoline and electrical panels in a garage. These are fire hazards of:','["ordinary combustibles, flammable liquids and electrical equipment", "water sources", "sports gear", "decorations"]'::jsonb,0,'Different materials create different hazards.','original'),
('127.756.d.7.C',4,'Storing gasoline in an unapproved container near a water heater is hazardous because:','["it smells nice", "flammable vapors can ignite", "it saves space", "gasoline sinks"]'::jsonb,1,'Vapors travel to ignition sources.','original'),
('127.756.d.7.D',3,'A CERT trainee learns that Class A involves wood and paper while Class B involves liquids. This describes:','["the sizes of nozzles", "the lengths of ladders", "the classes of fires", "the colors of hoses"]'::jsonb,2,'Classes guide agent selection.','original'),
('127.756.d.7.D',4,'A fire in an energized electrical panel is a:','["Class A fire", "Class K fire", "Class B fire", "Class C fire"]'::jsonb,3,'Class C = energized electrical.','original'),
('127.756.d.8.A',3,'A volunteer closes doors to confine a small room fire and shuts off nearby gas. These are:','["fire containment techniques", "fire fuels", "fire starters", "fire sparks"]'::jsonb,0,'Closing doors limits spread.','original'),
('127.756.d.8.A',4,'Closing a door behind you when leaving a burning room helps to:','["add oxygen", "slow fire spread and smoke movement", "speed the fire", "feed the fire"]'::jsonb,1,'A closed door contains the fire.','original'),
('127.756.d.8.B',3,'A trainee compares gasoline, kerosene and lighter fluid as materials that make fires start or spread faster. These are:','["fire doors", "fire alarms", "fire accelerants and fuels", "fire extinguishers"]'::jsonb,2,'Accelerants speed ignition.','original'),
('127.756.d.8.B',4,'An accelerant is a substance that:','["cools a fire", "puts out fires", "measures heat", "helps a fire start or spread faster"]'::jsonb,3,'Accelerants intensify fire.','original'),
('127.756.d.8.C',3,'A volunteer picks a dry chemical extinguisher for a gasoline fire rather than using water. This is selecting:','["appropriate resources based on the fuel", "any tool", "no tool", "a random tool"]'::jsonb,0,'Fuel type decides the agent.','original'),
('127.756.d.8.C',4,'Using water on a grease fire is dangerous because it can:','["cool it safely", "spread the burning grease", "stop it", "smother it"]'::jsonb,1,'Water splashes burning oil.','original'),
('127.756.d.8.D',3,'A trainee reads symbols, class ratings and instructions printed on an extinguisher. This explains information on:','["food labels", "road signs", "fire extinguisher labels", "clothing tags"]'::jsonb,2,'Labels list class, range and use.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Career Development' and d.language = 'en'
on conflict (fingerprint) do nothing;
insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'cte_99_v1'
from (values
('127.756.d.8.D',4,'An extinguisher label marked ''ABC'' means it can be used on:','["only grease", "only wood", "only metals", "ordinary combustibles, flammable liquids and electrical fires"]'::jsonb,3,'Multipurpose rating.','original'),
('127.756.d.8.E',3,'A class compares water, dry chemical and CO2 extinguishers and labels the handle, pin, hose and gauge. This identifies:','["types of extinguishers and components of a portable extinguisher", "types of pumps", "types of ladders", "types of tools"]'::jsonb,0,'Parts and types matter.','original'),
('127.756.d.8.E',4,'The gauge on a pressurized extinguisher shows whether it is:','["recently painted", "properly charged", "old", "lightweight"]'::jsonb,1,'Gauge shows pressure.','original'),
('127.756.d.8.F',3,'A volunteer pulls the pin, aims low, squeezes the handle and sweeps on a practice fire. This simulates the use of:','["a ladder", "a hose line", "a portable extinguisher using the PASS steps", "an axe"]'::jsonb,2,'PASS describes extinguisher use.','original'),
('127.756.d.8.F',4,'The ''S'' that follows ''Squeeze'' in PASS stands for:','["stand", "stop", "step", "sweep"]'::jsonb,3,'Sweep side to side.','original'),
('127.756.d.8.G',3,'A CERT team reviews the local fire department''s standard operating procedures for when volunteers may fight a small fire. This compares:','["best practices for fire suppression based on local standard operating procedures", "unrelated rules", "rumors", "menus"]'::jsonb,0,'Follow local SOPs.','original'),
('127.756.d.8.G',4,'A CERT volunteer should attempt to fight a fire only if the fire is:','["filled with smoke", "small and an escape route is clear", "blocking all exits", "large and spreading"]'::jsonb,1,'Safety first.','original'),
('127.756.d.9.A',3,'A volunteer evaluates the risks of a chemical that is toxic, flammable and corrosive. This identifies:','["benefits of hazards", "fashion trends", "risks associated with characteristics of hazardous materials", "recipes"]'::jsonb,2,'Characteristics determine risk.','original'),
('127.756.d.9.A',4,'A corrosive chemical is dangerous mainly because it can:','["change color only", "make noise", "freeze items", "burn skin and eat through materials"]'::jsonb,3,'Corrosives damage tissue.','original'),
('127.756.d.9.B',3,'A trainee sorts materials such as explosives, gases, flammable liquids and radioactive items into classes. This classifies hazardous materials according to the:','["National Fire Protection Association or Department of Transportation system", "telephone system", "school system", "grading system"]'::jsonb,0,'HazMat has standard classes.','original'),
('127.756.d.9.B',4,'Compressed gases, flammable liquids and explosives are examples of:','["music types", "hazardous material classes", "fruit types", "tool types"]'::jsonb,1,'Classes group hazards.','original'),
('127.756.d.9.C',3,'A diamond on a warehouse door has four colored squares with numbers. This is the:','["parking permit", "fire alarm", "NFPA 704 placard", "fire exit sign"]'::jsonb,2,'NFPA 704 communicates hazards.','original'),
('127.756.d.9.C',4,'The NFPA 704 diamond is designed to quickly show responders:','["the owner''s name", "the building''s age", "the rent amount", "the health, fire and reactivity hazards of a material"]'::jsonb,3,'It summarizes hazards.','original'),
('127.756.d.9.D',3,'On the NFPA diamond, blue stands for health, red for flammability and yellow for reactivity. This explains:','["the meaning of hazardous material placard colors and numbers", "the color of cars", "the weight of hoses", "the flavor of foods"]'::jsonb,0,'Colors map to hazard types.','original'),
('127.756.d.9.D',4,'On an NFPA 704 diamond, the red section indicates:','["storage", "flammability", "health", "reactivity"]'::jsonb,1,'Red = fire hazard.','original'),
('127.756.d.9.E',3,'A volunteer reads abbreviations and symbols such as ''W'' with a line through it, meaning no water. These are common:','["game pieces", "menu items", "acronyms and symbols used by the NFPA", "road signs"]'::jsonb,2,'NFPA uses special symbols.','original'),
('127.756.d.9.E',4,'A white section on the NFPA diamond with a ''W'' crossed out means the material:','["is safe in water", "is non-flammable", "glows", "reacts with water"]'::jsonb,3,'Avoid using water.','original'),
('127.756.d.10.A',3,'In a practice session, a volunteer places one hand on a manikin''s forehead and lifts the chin to open the airway. This simulates:','["the head tilt-chin lift method", "a splint", "a bandage wrap", "a log roll"]'::jsonb,0,'Head tilt-chin lift opens the airway.','original'),
('127.756.d.10.A',4,'The head tilt-chin lift is used to:','["splint a bone", "open the airway of an unconscious patient", "stop bleeding", "cool a patient"]'::jsonb,1,'It moves the tongue away from the airway.','original'),
('127.756.d.10.B',3,'A trainee learns that bleeding can be arterial, venous or capillary. These are the:','["types of burns", "types of fractures", "primary types of bleeding", "types of shock"]'::jsonb,2,'Bleeding types differ.','original'),
('127.756.d.10.B',4,'The first step to control most external bleeding is to:','["wash it only", "apply heat", "wait", "apply direct pressure to the wound"]'::jsonb,3,'Direct pressure is first-line.','original'),
('127.756.d.10.C',3,'A student researches how a drop in blood flow can starve organs of oxygen. This explains the:','["physiological effects of shock", "effects of music", "effects of boredom", "effects of sunlight"]'::jsonb,0,'Shock deprives tissues of oxygen.','original'),
('127.756.d.10.C',4,'Shock is a life-threatening condition because it:','["raises energy", "reduces blood flow to vital organs", "improves circulation", "cools the body"]'::jsonb,1,'Poor perfusion harms organs.','original'),
('127.756.d.10.D',3,'A volunteer notices a victim with clammy skin, a rapid pulse and nausea. These are:','["signs of fitness", "signs of sleep", "signs of shock", "signs of hunger"]'::jsonb,2,'These suggest shock.','original'),
('127.756.d.10.D',4,'Which is a sign of shock?','["flushed cheeks", "warm, dry skin", "slow pulse always", "pale, cool, clammy skin"]'::jsonb,3,'Skin changes indicate shock.','original'),
('127.756.d.10.E',3,'In a drill, volunteers cover a manikin with a blanket, lay it flat and call for help. This simulates procedures for:','["treating victims of shock", "ignoring victims", "moving victims quickly", "giving food"]'::jsonb,0,'Treat for shock to stabilize.','original'),
('127.756.d.10.E',4,'A basic step in treating a person in shock is to:','["let them walk", "keep them warm and call for emergency help", "give a large meal", "cool them rapidly"]'::jsonb,1,'Warmth and EMS.','original'),
('127.756.d.10.F',3,'A volunteer elevates a patient''s legs about 12 inches (if no injury prevents it) and covers them to keep warm. This is a technique for:','["removing debris", "cooking food", "controlling symptoms of shock", "starting fires"]'::jsonb,2,'Leg elevation helps blood flow.','original'),
('127.756.d.10.F',4,'Raising the legs of a shock victim may help because it:','["makes them cold", "causes injury", "slows breathing", "helps blood return to vital organs"]'::jsonb,3,'Elevation shifts blood to core.','original'),
('127.756.d.10.G',3,'A trained volunteer gives chest compressions and rescue breaths on a manikin at the correct rate and depth. This demonstrates:','["cardiopulmonary resuscitation (CPR)", "splinting", "burn care", "bandaging"]'::jsonb,0,'CPR maintains circulation.','original'),
('127.756.d.10.G',4,'Hands-only CPR compressions for an adult are given at a rate of about:','["60 per minute", "100 to 120 per minute", "200 per minute", "20 per minute"]'::jsonb,1,'AHA recommends 100–120.','original'),
('127.756.d.10.H',3,'A volunteer turns on a trainer unit, attaches pads and follows voice prompts. This demonstrates the use of an:','["fire extinguisher", "splint kit", "automated external defibrillator (AED)", "hose line"]'::jsonb,2,'AEDs deliver a shock when advised.','original'),
('127.756.d.10.H',4,'An AED is used on a person who:','["has a cut", "is hungry", "has a headache", "is unresponsive and not breathing normally"]'::jsonb,3,'AEDs treat cardiac arrest.','original'),
('127.756.d.11.A',3,'After a flood, volunteers wash hands with soap or sanitizer before eating and set up a handwashing station. This explains steps to maintain:','["proper hygiene during a disaster", "no hygiene", "bad habits", "poor hygiene"]'::jsonb,0,'Hygiene prevents disease.','original'),
('127.756.d.11.A',4,'During a disaster, the most effective way to prevent spreading illness is to:','["skip washing", "wash hands with soap and clean water", "avoid all water", "share utensils"]'::jsonb,1,'Handwashing prevents infection.','original'),
('127.756.d.11.B',3,'A camp crew buries human waste away from water sources and bags trash. This explains how to dispose of:','["fresh food", "clean water", "bacterial sources and waste during a disaster", "new tools"]'::jsonb,2,'Proper disposal prevents contamination.','original'),
('127.756.d.11.B',4,'Human waste during a disaster should be disposed of:','["beside the camp", "anywhere", "in a stream", "away from water sources and living areas"]'::jsonb,3,'Prevents contamination.','original'),
('127.756.d.11.C',3,'A team tests a filter and treats a water sample with purification tablets. This tests the use of a:','["water purification system", "air purifier", "radio", "oil filter"]'::jsonb,0,'Purification makes water safer to drink.','original'),
('127.756.d.11.C',4,'If no purification system is available, one safe method to treat water is to:','["add sugar", "boil it for at least one minute", "let it sit in the sun briefly", "freeze it"]'::jsonb,1,'Boiling kills most pathogens.','original'),
('127.756.d.12.A',3,'At a mass-casualty event, a volunteer quickly checks breathing, circulation and mental status to sort victims by priority. This is the concept of:','["random sorting", "simple cleaning", "simple triage and rapid treatment (START)", "slow transport"]'::jsonb,2,'START sorts quickly.','original'),
('127.756.d.12.A',4,'Triage means to:','["avoid treating anyone", "treat everyone equally", "move victims quickly", "sort victims by urgency of treatment"]'::jsonb,3,'Triage prioritizes care.','original'),
('127.756.d.12.B',3,'A disaster plan lists triage, treatment, transport and documentation as parts of medical operations. These are:','["major sub-functions of disaster medical operations", "hobbies", "extra jobs", "unrelated tasks"]'::jsonb,0,'Medical ops have sub-functions.','original'),
('127.756.d.12.B',4,'Which is a sub-function of disaster medical operations?','["fundraising", "treatment of patients", "decorating", "sports"]'::jsonb,1,'Treatment is a core function.','original'),
('127.756.d.12.C',3,'A team chooses a triage area close to the incident but away from hazards, with room and shelter. This selects and evaluates:','["a parking lot", "a school", "a designated triage area based on proximity to the incident", "a store"]'::jsonb,2,'Triage sites must be near but safe.','original'),
('127.756.d.12.C',4,'A triage area should be located:','["far from the scene", "behind locked doors", "inside the hazard", "near the incident yet safe from hazards"]'::jsonb,3,'Balance proximity and safety.','original'),
('127.756.d.12.D',3,'A volunteer checks that ambulances can reach the triage area and leave easily. This evaluates the area for:','["accessibility by transportation", "parking fees", "decorations", "scenic views"]'::jsonb,0,'Transport access is crucial.','original'),
('127.756.d.12.D',4,'When choosing a triage site, planners should confirm it has:','["only footpaths", "clear routes for ambulances to enter and exit", "no road access", "only one narrow lane"]'::jsonb,1,'Access speeds transport.','original'),
('127.756.d.12.E',3,'Victims needing immediate care, delayed care and those who have died are sent to separate areas. This assigns:','["random areas", "no areas", "triage areas for immediate care, delayed care and morgue operations", "one area for all"]'::jsonb,2,'Separate areas by category.','original'),
('127.756.d.12.E',4,'In triage, ''immediate'' victims are those who:','["can wait several hours", "are not hurt", "have died", "need lifesaving treatment right away"]'::jsonb,3,'Immediate = urgent.','original'),
('127.756.d.12.F',3,'A volunteer writes names, injuries, treatment given and destination on a tag attached to each victim. This develops:','["a documentation protocol for triage victims", "a team chant", "a grocery list", "a party plan"]'::jsonb,0,'Tags track victims.','original'),
('127.756.d.12.F',4,'A triage tag should include:','["only a nickname", "the victim''s condition and treatment given", "only the weather", "only the time of day"]'::jsonb,1,'Tags record patient info.','original'),
('127.756.d.13.A',3,'A volunteer performs a head-to-toe check and notes bruising, swelling and deformity. These are:','["signs of luck", "signs of fitness", "indicators of injury", "signs of laziness"]'::jsonb,2,'Look for DCAP-BTLS signs.','original'),
('127.756.d.13.A',4,'Which is an indicator of injury found during a head-to-toe assessment?','["a smile", "clean clothes", "smooth skin", "swelling or deformity"]'::jsonb,3,'Swelling and deformity signal injury.','original'),
('127.756.d.13.B',3,'A trainee sorts minor cuts from life-threatening injuries and chooses the right level of care. This distinguishes:','["the severity of injuries and the appropriate response", "only size", "only age", "only color"]'::jsonb,0,'Severity guides action.','original'),
('127.756.d.13.B',4,'A life-threatening injury, such as severe uncontrolled bleeding, should be:','["treated last", "treated first and EMS called", "ignored", "reported later"]'::jsonb,1,'Life threats come first.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Career Development' and d.language = 'en'
on conflict (fingerprint) do nothing;
insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'cte_99_v1'
from (values
('127.756.d.13.C',3,'A volunteer notes where a wound is located and what type it appears to be, then records it. This is documenting:','["game scores", "lunch plans", "patient injuries, including location and type", "travel times"]'::jsonb,2,'Documentation aids care.','original'),
('127.756.d.13.C',4,'Recording an injury''s location and type helps because it:','["delays care", "hides information", "wastes time", "informs later responders about care needs"]'::jsonb,3,'Records support handoff.','original'),
('127.756.d.13.D',3,'A concussion, a neck injury and a spinal injury are examples of:','["closed-head, neck or spinal injuries", "sprains only", "bites", "burns"]'::jsonb,0,'These are serious injuries.','original'),
('127.756.d.13.D',4,'If a spinal injury is suspected, a volunteer should:','["move them quickly", "keep the person still and call for help", "sit them up", "walk them out"]'::jsonb,1,'Avoid movement.','original'),
('127.756.d.14.A',3,'A student labels the epidermis, dermis and subcutaneous layers. This defines the:','["parts of the heart", "bones of the leg", "layers of skin", "types of muscle"]'::jsonb,2,'Skin has three layers.','original'),
('127.756.d.14.A',4,'The outermost layer of skin is the:','["bone", "dermis", "subcutaneous layer", "epidermis"]'::jsonb,3,'Epidermis is outer.','original'),
('127.756.d.14.B',3,'A volunteer decides that a burn with redness only is first degree, blisters is second degree and charring is third degree. This classifies:','["the severity of burns", "the length of a ladder", "the size of a hose", "the weight of a tank"]'::jsonb,0,'Burn depth is classified by degree.','original'),
('127.756.d.14.B',4,'A burn that causes blisters is generally:','["no degree", "second degree", "third degree", "first degree"]'::jsonb,1,'Second-degree burns blister.','original'),
('127.756.d.14.C',3,'A volunteer applies direct pressure, elevates the limb and adds more dressing when blood soaks through. This is controlling:','["a crowd", "a fire", "bleeding and preventing severe blood loss", "a flood"]'::jsonb,2,'Bleeding control saves lives.','original'),
('127.756.d.14.C',4,'If blood soaks through a dressing, the volunteer should:','["remove it", "wash it", "stop pressure", "add another dressing on top and keep pressure"]'::jsonb,3,'Do not remove the first dressing.','original'),
('127.756.d.14.D',3,'A trainee rinses a minor wound with clean water and covers it with a sterile bandage. This simulates:','["cleaning wounds and applying dressings and bandages", "leaving wounds open", "using dirt", "tying tightly"]'::jsonb,0,'Clean and cover.','original'),
('127.756.d.14.D',4,'A minor wound should be covered with a:','["plastic only", "clean, sterile dressing", "dirty cloth", "tape alone"]'::jsonb,1,'Sterile cover prevents infection.','original'),
('127.756.d.14.E',3,'A volunteer finds a knife embedded in a leg and stabilizes it with padding rather than pulling it out. This is managing:','["a sprain", "a rash", "a foreign object in a wound", "a burn"]'::jsonb,2,'Do not remove embedded objects.','original'),
('127.756.d.14.E',4,'When an object is embedded in a wound, a first responder should:','["twist it", "pull it out", "push it deeper", "leave it in place and stabilize it"]'::jsonb,3,'Removal can worsen bleeding.','original'),
('127.756.d.14.F',3,'A volunteer uses padding and a rigid support to hold a broken wrist still above and below the joint. This demonstrates:','["immobilization of joints", "moving joints", "stretching joints", "rubbing joints"]'::jsonb,0,'Splints immobilize.','original'),
('127.756.d.14.F',4,'A splint should immobilize the injured bone and the joints:','["far away", "above and below the injury", "only at the injury", "only below"]'::jsonb,1,'Immobilize adjacent joints.','original'),
('127.756.d.15.A',3,'Before entering a collapsed building, a team looks at hazards, victims and resources, then forms a plan. This is to:','["ignore hazards", "wait for a miracle", "assess a rescue scene and formulate a plan of action", "rush in"]'::jsonb,2,'Size-up first.','original'),
('127.756.d.15.A',4,'The first step in a light search and rescue operation is to:','["enter immediately", "call it off", "ignore victims", "size up the situation and assess hazards"]'::jsonb,3,'Size-up precedes action.','original'),
('127.756.d.15.B',3,'Teams use cribbing and leverage to remove debris and extricate victims safely. These are:','["safe techniques for debris removal and extrication", "random digging", "guesses", "unsafe shortcuts"]'::jsonb,0,'Use safe lifting techniques.','original'),
('127.756.d.15.B',4,'When removing debris, rescuers should lift with their:','["neck", "legs, keeping the back straight", "back", "arms only"]'::jsonb,1,'Protect the back.','original'),
('127.756.d.15.C',3,'A leader gives each volunteer a role such as digging, spotting or carrying and rotates them to avoid fatigue. This creates:','["chaos", "no plan", "a plan for assigning staff to debris removal and extrication tasks", "a vacation schedule"]'::jsonb,2,'Task assignments improve safety.','original'),
('127.756.d.15.C',4,'Rotating rescuers during heavy work helps to:','["increase fatigue", "slow response", "raise noise", "reduce fatigue and injury"]'::jsonb,3,'Rotation protects teams.','original'),
('127.756.d.15.D',3,'A team gathers cribbing, shoring and ropes to stabilize unstable structures near a victim. This identifies:','["materials for stabilizing hazards at an accident scene", "cooking items", "fun materials", "art supplies"]'::jsonb,0,'Shoring and cribbing stabilize.','original'),
('127.756.d.15.D',4,'Wooden blocks stacked to support a heavy object are called:','["kindling", "cribbing", "shingles", "tinder"]'::jsonb,1,'Cribbing supports loads.','original'),
('127.756.d.15.E',3,'Before lifting a heavy beam off a victim, a team places blocks to prevent it from dropping. This describes how to:','["shake the beam", "lift quickly", "stabilize an object prior to lifting", "drop the object"]'::jsonb,2,'Stabilize before lifting.','original'),
('127.756.d.15.E',4,'Stabilizing an object before lifting helps ensure:','["greater risk", "less planning", "more noise", "responder and victim safety"]'::jsonb,3,'Prevents collapse.','original'),
('127.756.d.15.F',3,'A team uses a lever and cribbing to lift a beam a few inches, then checks the load and adjusts. This simulates a lift and:','["troubleshoots possible issues", "speeds work blindly", "adds hazards", "ignores issues"]'::jsonb,0,'Check and adjust during lifts.','original'),
('127.756.d.15.F',4,'During a lift, if the load shifts unexpectedly, rescuers should:','["walk away", "stop, re-stabilize and reassess", "keep lifting", "add weight"]'::jsonb,1,'Safety first.','original'),
('127.756.d.17.A',3,'A leader sorts tasks into those a volunteer team can do and those needing specialized units. This classifies:','["gifts", "trips", "response activities based on team capabilities and training", "recipes"]'::jsonb,2,'Know your limits.','original'),
('127.756.d.17.A',4,'A CERT team should avoid response tasks that:','["are simple", "match their training", "are safe", "exceed the team''s training and capability"]'::jsonb,3,'Stay within training.','original'),
('127.756.d.17.B',3,'At a scene with a trapped victim, a team determines whether to do a light rescue or call heavy rescue units. This evaluates:','["an accident scene involving a trapped victim", "a game", "a parade", "a party"]'::jsonb,0,'Decide response level.','original'),
('127.756.d.17.B',4,'If a victim is trapped under heavy concrete, a CERT team should:','["ignore it", "call for specialized heavy rescue", "use fire", "lift it alone"]'::jsonb,1,'Heavy rescue needs specialists.','original'),
('127.756.d.17.C',3,'Using plain language and standard terms like ''victim'' and ''hazard'' avoids confusion on the radio. This defines:','["secret codes", "slang", "common terminology that supports communication", "jokes"]'::jsonb,2,'Clear terms prevent errors.','original'),
('127.756.d.17.C',4,'Using clear, common terminology during a response helps:','["hide plans", "delay action", "confuse others", "teams understand one another"]'::jsonb,3,'Clarity is key.','original'),
('127.756.d.17.D',3,'A leader assigns team roles such as safety officer, search team and documenter based on how big the incident is. This determines:','["team member roles based on incident scope", "single roles", "no roles", "random roles"]'::jsonb,0,'Scope shapes roles.','original'),
('127.756.d.17.D',4,'In a larger incident, a CERT team leader should:','["ignore members", "assign clear roles and keep track of members", "avoid delegating", "do everything alone"]'::jsonb,1,'Roles keep order.','original'),
('127.756.d.18.A',3,'A volunteer speaks calmly and clearly with a frightened survivor, listens and avoids jargon. This describes appropriate:','["blame", "jokes", "communication techniques for crises and disasters", "shouting"]'::jsonb,2,'Calm talk helps.','original'),
('127.756.d.18.A',4,'When speaking with a disaster survivor, a volunteer should:','["interrupt", "argue", "blame", "speak calmly and listen actively"]'::jsonb,3,'Support through listening.','original'),
('127.756.d.18.B',3,'Survivors may feel fear, anger, numbness and grief after a disaster. This explains the:','["emotional responses that can follow a disaster", "weather", "physical injuries", "building codes"]'::jsonb,0,'Emotions vary.','original'),
('127.756.d.18.B',4,'A common emotional reaction after a disaster is:','["no reaction ever", "anxiety or numbness", "loud laughter always", "permanent joy"]'::jsonb,1,'Stress reactions are common.','original'),
('127.756.d.18.C',3,'Rescuers share information, provide water and a quiet area and explain what will happen next. This identifies steps to:','["hurry survivors", "hide information", "reduce stressors on disaster survivors", "increase stress"]'::jsonb,2,'Information and comfort reduce stress.','original'),
('127.756.d.18.C',4,'One way to reduce stress for survivors is to:','["rush them", "ignore questions", "leave them alone", "keep them informed and offer basic comforts"]'::jsonb,3,'Information calms.','original'),
('127.756.d.18.D',3,'After long shifts, a rescuer shows exhaustion, irritability and difficulty sleeping. This analyzes:','["psychological and physiological responses in rescuers", "signs of boredom", "signs of fitness", "signs of calm"]'::jsonb,0,'Rescuers can be affected.','original'),
('127.756.d.18.D',4,'Prolonged rescue work can lead to rescuer symptoms such as:','["new energy always", "fatigue and emotional strain", "no stress", "perfect memory"]'::jsonb,1,'Stress and fatigue are common.','original'),
('127.756.d.18.E',3,'A survivor feels guilty for surviving while a rescuer feels overwhelmed. This describes potential:','["joyful events", "rare events", "emotional responses experienced by survivors and rescuers", "no responses"]'::jsonb,2,'Both can feel strong emotions.','original'),
('127.756.d.18.E',4,'A potential emotional response among both survivors and rescuers is:','["none", "boredom only", "pride only", "grief or guilt"]'::jsonb,3,'Grief and guilt are common.','original'),
('127.756.d.18.F',3,'On the scene, trained responders offer calm support to reduce distress and connect people to help. This explains the goals of:','["on-scene psychological intervention", "teaching math", "ignoring people", "fixing cars"]'::jsonb,0,'Aims to stabilize and support.','original'),
('127.756.d.18.F',4,'A goal of on-scene psychological support is to:','["diagnose illnesses", "reduce distress and help people cope", "assign blame", "delay aid"]'::jsonb,1,'Early support helps coping.','original'),
('127.756.d.19.A',3,'A student defines terms such as ''terrorism'', ''homeland security'' and ''threat''. This defines:','["recipes", "sports", "vocabulary related to terrorism and homeland security", "poems"]'::jsonb,2,'Know the vocabulary.','original'),
('127.756.d.19.A',4,'The term ''homeland security'' refers to efforts to:','["start wars", "run schools", "raise taxes", "prevent and respond to attacks within the country"]'::jsonb,3,'Security protects the nation.','original'),
('127.756.d.19.B',3,'A volunteer learns to notice unattended packages, odd odors and unusual crowds as warning signs. This identifies:','["environmental indicators and warning signs of terrorist activity", "signs of sale", "signs of fun", "signs of rain"]'::jsonb,0,'Be alert and report.','original'),
('127.756.d.19.B',4,'If a CERT volunteer notices a suspicious unattended bag in a crowded place, the best action is to:','["kick it", "stay away and report it to authorities", "move it", "open it"]'::jsonb,1,'Report; do not touch.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Career Development' and d.language = 'en'
on conflict (fingerprint) do nothing;
